"use strict";(self.webpackChunkcolemanlindberg=self.webpackChunkcolemanlindberg||[]).push([[12],{2708:(n,e,a)=>{a.r(e),a.d(e,{default:()=>A});const t=a.p+"static/media/01GingerbreadMan.a79f47984da6f13b487b.wav",o=a.p+"static/media/02SkyAsIs.2b7de074442bc9676128.wav",i=a.p+"static/media/03FastFoodHeaven.eaaea7b078a2d2b22c9b.wav",s=a.p+"static/media/04FadedStar.7b0bec6043590014171f.wav",r=a.p+"static/media/05OwnTheView.ed77233103847b25e289.wav",h=a.p+"static/media/06Resolutions.937fd6bce49ab782b491.wav",l=a.p+"static/media/07TiredOfSnow.408a82bff4b9e0310ece.wav",d=a.p+"static/media/08GingerbreadMan.c80959c43d9d80a654ab.wav",c=a.p+"static/media/09HappyNow.66afa7156b51a70ce4bc.wav",u=a.p+"static/media/10SlowNewsDay.9bb3dfc3e9ac621cc1f4.wav",w=a.p+"static/media/cole_grass.777d3fdc40b147fcc6a2.jpeg",m=a.p+"static/media/otv_cover.6425e8ae5e73358dbf9c.jpg",g=[{track:"Gingerbread Man",lyrics:"I fly by night\nI fly above\nFar beneath a starry dome\nI don\u2019t look back\nI\u2019m unconcerned\nWith my crimson tracks\nOr the bridges I\u2019ve burned\n\nRun run run as fast as you can\nYou can\u2019t catch me I\u2019m the Gingerbread Man\nAnd I\u2019m sweet sweet sweet til I snap\nYou don\u2019t want that\n\nI\u2019m making sure\nA path is clear\nAnd I\u2019m wearing out my welcome here\nWhen I tear out\nYou feel my wake\nThe sidewalk shouts and the city shakes\n\nRun run run as fast as you can\nYou can\u2019t catch me I\u2019m the Gingerbread Man\nAnd I\u2019m sweet sweet sweet til I snap\nYou don\u2019t want that\n\nOh, come and get me\nDon\u2019t let me get away\nOh, come and get me\nDon\u2019t let me go astray\n\nSo will I sail\nOr will I fall\nWill I soar or\nWill I crawl\nThis runaway is getting tired\nOf the smell of fear and the smell of fire\n\nRun run run as fast as you can\nYou can\u2019t catch me I\u2019m the Gingerbread Man\nAnd I\u2019m sweet sweet sweet til I snap\nYou don\u2019t want that"},{track:"Sky As Is",lyrics:"You and I both dreamed of deer\nCurled up on your bed\nYour hair got so unruly\nWe finally shaved your head\nWe\u2019d mock the boxcar monsters\nCome home with 10 seconds to spare\n\nYou had that rundown Ford\nWe liked to drive around\nIt had that built-in boyfriend smell\nAnd stereo sound\nGod bless the makeout mobile\nIn the backseat\nIn the dark\n\n(See that star? I\u2019ll take it down for you)\n\nNow we look up\nTo the stars at night\nAnd we look out for\nThe Northern Lights\nWe don\u2019t have to understand them\nIf we just take the sky as is"},{track:"Fast Food Heaven",lyrics:"Decide who\u2019s gonna drive\nNorth on 35\nIt\u2019s early morning\nOr late at night\nDouble cheeseburger\nAnd a couple fries\nSo high\n\nI can be tape\nI can be a raincoat\nI can be whatever you want\nLet\u2019s go smoke\nI can be the first\nOr I can be the last\nI can be all that\n\nDecide who\u2019s gonna drive\nNorth on 35\nIt\u2019s early morning\nOr late at night\nSlide down to the water\nClimb back up to the bridge\nSo high\n\nJust take me dancing\nI gotta know\nIf you\u2019re really into\nMy little show\nI wake up in the morning\nAnd I put on this disguise\n\nI can be tape\nI can be a raincoat\nI can be whatever you want\nLet\u2019s go smoke\nI can be the first\nOr I can be the last\nI can be all that\nI can be slow\nI can be fast\nI can be all that\n\nI would be your\nJanesville and Milwaukee\nOsseo, Kenosha\nMenomone and Hudson\nI would be your\nMadison and Wausau\nAppleton, Black River\nEau Claire and Winona"},{track:"Faded Star",lyrics:"Washed up on the city shore\nCrawling on the city floor\nBroken boys on a bus\nWhat are they gonna do with us?\n\nGood hearts\nThe best there are\nUp on our tippy toes\nTo touch a faded star\nCuz there\u2019s still some light\nAnd it\u2019s come so far\n\nMoving through the city streets\nMoving to the city beat\nBroken boys on a bus\nWhat are the going to do with us?\n\nGood hearts\nThe best there are\nUp on our tippy toes\nTo touch a faded star\nCuz there\u2019s still some light\nAnd it\u2019s come so far\n\nIt\u2019s a deep and lonely well\nIt\u2019s an easy lie to tell\nIt\u2019s a deep and lonely shame\nFamiliar as our names\n\nI press myself against this adolescent air\nIncandessant traffic\nI don\u2019t care to talk about it\nWhen I\u2019m this pissed off I walk about it\nGutter, politics\nThe labels stick, I\u2019m stuck\nEroding ruts, curb cuts\nCity-wide, city-worn\nThis boys torn\nBut is he still born?\nOr is he stillborn?\n\nLit up like the city lights\nFalling like the city night\nBroken boys on a bus\nWhat are they going to do with us?\n\nIt\u2019s a deep and lonely well\nIt\u2019s an easy lie to tell\nIt\u2019s a deep and lonely shame\nFamiliar as our names"},{track:"Own The View",lyrics:"They own the buildings\nBut we own the view\nThey own the papers\nBut we own the truth\nThey own the airwaves\nBut we own what\u2019s real\nThe things we can touch now\nThe things we can feel\n\nCome on, let\u2019s go now\nA new night is calling\nThough the darkness is deep\nAnd the angels are falling\nTake to the freeway\nTake to the sky\nDream a new dream now\nAnd fly, fly, fly\n\nDown here in the mean streets\nPurpetual motion\nJunkies and jesters\nDust and devotion\nWe\u2019re not scared to get dirty\nWe\u2019re not scared to get clean\nNot scared of our own stories or\nThe sorrow we\u2019ve seen\n\nCome on, let\u2019s go now\nA new night is calling\nThough the darkness is deep\nAnd the angels are falling\nTake to the freeway\nTake to the sky\nDream a new dream now\nAnd fly, fly, fly\n\nAnother tornado\nAnother hard rain\nAnd we survey the damage\nOur hearts have sustained\n And we wake every morning and say\n\u201dI wanna live\nAnd give all I can give\n\nThey own the buildings\nBut we own the view\nThey say that we\u2019re crazy\nAnd it\u2019s probably true\nBut we\u2019re the ones who bear witness\nAnd write it all down\nWith a song to the city\nWith our hymns to this town\n\nCome on, let\u2019s go now\nA new night is calling\nThough the darkness is deep\nAnd the angels are falling\nTake to the freeway\nTake to the sky\nDream a new dream now\nAnd fly, fly, fly"},{track:"Resolutions",lyrics:"We used to travel coast to coast\nI used to dream a little bigger\nNow I wake to the alarm\nFollow a schedule that predictable\nI hardly pick up my guitar\n It\u2019s funny how the one things that sustained me\nCould seem so foreign to me now\nLike winter after springtime\nI\u2019ve spent way too long in this town\n\nI keep my eyes turned to the ground\nI turn my shoulder to the cold\nMy feet dance in circles \u2018cross the ice\nI think I\u2019ll call you\nIt\u2019s been a while\nMy fingers follow yours again\nThe notes drift softly\nWe are old friends\nI\u2019m really quite judgemental but you know this\nI\u2019ll find a balance with forgiveness\nI\u2019ve spent too long in this town\nAnd now I feel old\nWe have shared some drinks in this town\nIt\u2019s in our history and it used to warm me\nBut it\u2019s been one long January\n\nThere\u2019s always something left undone\nI make excuses and I go to bed\nSomehow I\u2019m constantly exhausted\nSomewhere a war is always raging\nI weigh the obstacles and then\nI take in a breath and brace my feet\nAgainst the things that fill my head\nI see that compromise can be a good thing\nAnd I will leave some love in this town\n\nThere\u2019s more than cold that numbs my hands\nWe are clumsy, we are faded\nBut you always read between the lines\nAlways broke, desparate and jaded\nSo I will turn another page\nRemember tears, remember laughs\n dirty sidewalk in the rain\nCold radiators and Christmas lights\nOh I have shed my skin in this town\nOnce again\nWe\u2019ve burned bridges\nWe have lost hopes\nBut the sun still rises and it warms me\nAnd here is one more January\nLet\u2019s start again"},{track:"Tired Of Snow",lyrics:"I\u2019m tired of snow\nAnd I\u2019m tired of letting go\nTired of me and you\nnd all the hell we\u2019ve been through\n\nAnd I never did belong\nAnd I knew it all along\nThe way you treated me was wrong\nBaby, thanks for all the songs\n\nYou\u2019re scared to show your face\nSo back to your hiding place\nIt\u2019s finally your turn\nTo face the facts\nTo face the burn\n\nAnd I never did belong\nAnd I knew it all along\nThe way you treated me was wrong\nBaby, thanks for all the songs\nIn a graveyard full of ghosts\nYou have haunted me the most\nI\u2019m gonna bury all this pain\n\u2019Til only dust and bone remain\n\nI\u2019m tirade of snow\nAnd I\u2019m tired of letting go\n\nAnd I never did belong\nAnd I knew it all along\nThe way you treated me was wrong\nBaby, thanks for all the songs"},{track:"Gingerbread Man (Painted Whore Remix)",lyrics:"I fly by night\nI fly above\nFar beneath a starry dome\nI don\u2019t look back\nI\u2019m unconcerned\nWith my crimson tracks\nOr the bridges I\u2019ve burned\n\nRun run run as fast as you can\nYou can\u2019t catch me I\u2019m the Gingerbread Man\nAnd I\u2019m sweet sweet sweet til I snap\nYou don\u2019t want that\n\nI\u2019m making sure\nA path is clear\nAnd I\u2019m wearing out my welcome here\nWhen I tear out\nYou feel my wake\nThe sidewalk shouts and the city shakes\n\nRun run run as fast as you can\nYou can\u2019t catch me I\u2019m the Gingerbread Man\nAnd I\u2019m sweet sweet sweet til I snap\nYou don\u2019t want that\n\nOh, come and get me\nDon\u2019t let me get away\nOh, come and get me\nDon\u2019t let me go astray\n\nSo will I sail\nOr will I fall\nWill I soar or\nWill I crawl\nThis runaway is getting tired\nOf the smell of fear and the smell of fire\n\nRun run run as fast as you can\nYou can\u2019t catch me I\u2019m the Gingerbread Man\nAnd I\u2019m sweet sweet sweet til I snap\nYou don\u2019t want that"},{track:"Happy Now",lyrics:"Another day\nSpent the exact same way\nAnother year\nAnd I\u2019m still here\nThe city tries to grind\nBut we sit around and whine\nThe Seattle of the Midwest\nWith a big Manhattan complex\nSo I am walking downtown\nMy feet make contact with the ground\nThe ground is wet with rain\nAspiring to be snow someday\nAnd all the buildings here are tall\nThey keep the people feeling small\nKeep \u2018em busy pushing papers\nAnd saving all the joy later\n\nI am living on my own\nAnd I am picking at the bones\nOf a society that\nFeeds me mediocrity\nAnd I\u2019ve got bills to pay\nThat\u2019s why I\u2019m working everyday\nThe more I work, the more I\u2019m tired\nAnd I find it hard to be inspired\n\nBut I\u2019ve got wind in my throat\nAnd I\u2019m in love with every note\nAnd these fingers are all mine\nAnd they get me through the hard times\nAnd if I don\u2019t find a way\nTo do what I love everyday\nI know I\u2019m going to die inside\nLike every zombie I see passing by\n\nSo I am walking downtown\nMy feet make contact with the ground\nI cross against the light\nAnd nonchalantly risk my life\nAnd I\u2019ve forgotten where I\u2019m going\nThen I realize it\u2019s snowing\nAnd it\u2019s comforting somehow\nAt least the rain is happy now"},{track:"Slow News Day",lyrics:"I don\u2019t give a shit about Monica Lewinski\nI\u2019m just happy that she got laid\nWhile the world was spinning right out of control\nAnd the journalists were calling it a slow news day\n\nWe bombed Baghdad today\nGas prices haven\u2019t been this low in years\nThe economy in my town\u2019s looking up\nWe clench and smile \u201cyou betcha\u201d\n\nI don\u2019t give a shit about Monica Lewinski\nI\u2019m just happy that she got laid\nWhile the world was spinning right out of control\nAnd the journalists were calling it a slow news day\n\nA man and a woman on a corner downtown\nAre dancing cheek to cheek\nOblivious to my stare\nAnd I think it\u2019s great that they found love\nBut there\u2019s a scab on my heart\nThat just got picked open again\n\nCus October in Laramie, Wyoming\nA scarecrow on a deer fence\nBleeding in the cold\nAnd a woman help a sign up at his funeral\nThat said \u201cMatts in hell\u201d and \u201cFags doom nations\u201d\n\nI don\u2019t give a shit about Monica Lewinski\nI\u2019m just happy that she got laid\nWhile the world was spinning right out of control\nAnd the journalists were calling it a slow news day\n\nI walk the streets alone tonight\nThe snow is trying to fly\nIn a bitter cold December sky\nI felt the holes in my pockets\nLike I could piece them back together with my hands\n\nAnd I don\u2019t give a shit about it\nI don\u2019t give a fuck about it\nGive a flying fuck about it\n\nMatts in hell and fags doom nations\nI don\u2019t give a shit about Monica Lewinski"}],y=a.p+"static/media/bebe_curv.0b50e2ffa6f4ef8a87f3.JPG",b=Array.isArray(g)&&"string"===typeof g[0]?g.map(n=>JSON.parse(n)):g,I={album:"Own the View",cover:m,background:y,color:"#74c932",colorII:"#74c932",fontColor:"white",pic:w,about:"During the pandemic I had a lot of time on my hands, and I spent much of it digging through old boxes, reading journals I had saved, and rediscovering music and art that I had forgotten. One day I fired up an old, worn-out laptop and discovered a whole collection of songs I had recorded but never released. Most of them featured Henry Bishop on vocals, guitar, and hand drums. Some had been recorded as demos with Chad Dutton in 2011-2012 and had never made it onto an album. A couple were recorded during the Skylines sessions but were not included on that album for one reason or another. I decided to put these songs out under the name The Brotherbears, an homage to my little niece\u2019s name for me. While not a formal, fully realized album, Own The View is a heartfelt collection of songs that commemorate my friendship with Henry and provide a slice of life from parts of my musical journey that may have never seen the light of day had it not been for those long days in quarantine.",tracks:[{name:"Gingerbread Man",artist:"The Brotherbears",album:"Own The View",url:t,id:0,image:m,pic:w,background:y,lyrics:b[0].lyrics},{name:"Sky As Is",artist:"The Brotherbears",album:"Own The View",url:o,id:1,image:m,pic:w,background:y,lyrics:b[1].lyrics},{name:"Fast Food Heaven",artist:"The Brotherbears",album:"Own The View",url:i,id:2,image:m,pic:w,background:y,lyrics:b[2].lyrics},{name:"Faded Star",artist:"The Brotherbears",album:"Own The View",url:s,id:3,image:m,pic:w,background:y,lyrics:b[3].lyrics},{name:"Own The View",artist:"The Brotherbears",album:"Own The View",url:r,id:4,image:m,pic:w,background:y,lyrics:b[4].lyrics},{name:"Resolutions",artist:"The Brotherbears",album:"Own The View",url:h,id:5,image:m,pic:w,background:y,lyrics:b[5].lyrics},{name:"Tired Of Snow",artist:"The Brotherbears",album:"Own The View",url:l,id:6,image:m,pic:w,background:y,lyrics:b[6].lyrics},{name:"Gingerbread Man (Painted Whore Remix)",artist:"The Brotherbears",album:"Own The View",url:d,id:7,image:m,pic:w,background:y,lyrics:b[7].lyrics},{name:"Happy Now",artist:"The Brotherbears",album:"Own The View",url:c,id:8,image:m,pic:w,background:y,lyrics:b[8].lyrics},{name:"Slow News Day",artist:"The Brotherbears",album:"Own The View",url:u,id:9,image:m,pic:w,background:y,lyrics:b[9].lyrics}]};var f=a(7283),p=a(8540),k=a(5623),v=a(579);function A(){return(0,v.jsx)("div",{style:{display:"flex",alignItems:"center"},children:(0,v.jsx)(f.A,{album:I,background:I.background,AudioPlayer:p.A,AlbumAboutCard:k.A})})}}}]);
